type Tree is Data:
  Leaf{n: U32}
  Branch{l: Tree, r: Tree}
def f(t: Tree) -> U32:
  match t:
    case Branch{Leaf{x}, Leaf{y}}: U32.add(x, y)
    case _: 0
def main() -> U32:
  f(Branch{Leaf{20}, Leaf{22}})

